section.sourcecode:
; ===================================================================== ; DTN BASKET PROTOCOL GRAMMAR (RFC 8610) ; =====================================================================
protocol-version = 1 coap-status-code = uint .size 1 ; Codes de statut CoAP (RFC 7252)
; --------------------------------------------------------------------- ; 1. PANIER DE REQUÊTES (BASKET REQUEST) ; ---------------------------------------------------------------------
basket-request = { ? -1 => uint, ; Tag d'expérimentation (ex: 44444) 0 => uint, ; Version du protocole (protocol-version = 1) 1 => text / bytes, ; Identifiant unique de la requête (req_id) ? 2 => text, ; Destination de réponse optionnelle (reply_to EID) ? 3 => uint, ; Lifetime par défaut des bundles de réponse (ms/s) 4 => [* request-item] ; Tableau d'items ordonné par priorité }
request-item = { 0 => uint .default 0, ; Opération: 0=GET, 1=CHECK, 2=SEARCH, 3=CANCEL, 4=LIST 1 => text, ; URI / URN / CID / Tag ? 2 => uint, ; Taille maximale acceptée en octets (max_size) ? 3 => [* (uint / text)],; Formats acceptés (défaut = */*) ? 4 => [* bytes], ; Hachages tronqués déjà possédés (have_hashes) ? 5 => uint, ; Horodatage POSIX (if_modified_since) ? 6 => uint ; Surcharge du Lifetime pour la réponse de cet item (ms/s) }
; --------------------------------------------------------------------- ; 2. RÉPONSE APPLICATIVE DE MÉTADONNÉES (BASKET RESPONSE) ; ---------------------------------------------------------------------
basket-response = { ? -1 => uint, ; Tag d'expérimentation (ex: 44444) 0 => uint, ; Version du protocole (protocol-version = 1) 1 => text / bytes, ; Identifiant de la requête originale (req_id) 2 => [* item-response] ; Tableau des résultats par item }
item-response = { 0 => uint, ; Index de l'item dans le panier original (item_idx) 1 => coap-status-code, ; Code de statut CoAP (RFC 7252) ? 2 => item-metadata, ; Métadonnées du bundle de contenu ? 3 => text ; Message de diagnostic (si statut d'erreur) }
item-metadata = { 0 => bytes, ; Hash SHA-256 de la ressource (clé de corrélation) ? 1 => uint, ; Taille de la ressource en octets ? 2 => text, ; Type MIME / Format (ex: "text/markdown") ? 3 => text, ; URI / URN / CID explicite de la ressource ? 4 => uint ; Horodatage POSIX de dernière modification }
